def longest_consecutive_run(nums: list) -> int:
    num_set = set(nums)
    longest = 0
    for n in num_set:
        if n - 1 not in num_set:
            cur = n
            streak = 1
            while cur + 1 in num_set:
                cur += 1
                streak += 1
            longest = max(longest, streak)
    return longest

