def compress_string(s: str) -> str:
    if not s:
        return ''
    res = []
    cnt = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            cnt += 1
        else:
            res.append(s[i - 1] + str(cnt))
            cnt = 1
    res.append(s[-1] + str(cnt))
    compressed = ''.join(res)
    return compressed if len(compressed) < len(s) else s

