def group_anagrams_list(strs: list) -> list:
    from collections import defaultdict
    d = defaultdict(list)
    for s in strs:
        key = ''.join(sorted(s))
        d[key].append(s)
    res = [sorted(group) for group in d.values()]
    return sorted(res)

